import{_ as t,o as a,c as n,e as i}from"./chunks/framework.CJ137FEY.js";const g=JSON.parse('{"title":"Typography","description":"","frontmatter":{},"headers":[],"relativePath":"guide/typography.md","filePath":"guide/typography.md"}'),o={name:"guide/typography.md"};function l(r,e,d,s,c,f){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="typography" tabindex="-1">Typography <a class="header-anchor" href="#typography" aria-label="Permalink to &quot;Typography&quot;">​</a></h1><p>OreUI comes equipped with the authentic typography scale used in Minecraft Bedrock Edition, featuring pixel fonts for titles and clean Noto Sans for documentation reading.</p><hr><h2 id="🔤-font-hierarchy-overview" tabindex="-1">🔤 Font Hierarchy Overview <a class="header-anchor" href="#🔤-font-hierarchy-overview" aria-label="Permalink to &quot;🔤 Font Hierarchy Overview&quot;">​</a></h2><div class="oreui-frame"><div style="font-family:var(--font-mc-ten);font-size:28px;color:#FFFFFF;margin-bottom:8px;"> Minecraft Ten - 28px Hero &amp; Title Font </div><div style="font-family:var(--font-mc-seven);font-size:22px;color:#6CC349;margin-bottom:8px;"> Minecraft Seven - 22px Section Headers &amp; Card Titles </div><div style="font-family:var(--font-mc-five-bold);font-size:16px;color:#FFE866;margin-bottom:8px;"> Minecraft Five Bold - 16px Badges, Tags &amp; Micro Headers </div><div style="font-family:var(--font-noto-bold);font-size:15px;color:#D0D1D4;line-height:1.6;"> Noto Sans Bold - 15px Interactive Buttons, Form Labels, and UI Components. </div></div><hr><h2 id="📏-css-variables-guidelines" tabindex="-1">📏 CSS Variables &amp; Guidelines <a class="header-anchor" href="#📏-css-variables-guidelines" aria-label="Permalink to &quot;📏 CSS Variables &amp; Guidelines&quot;">​</a></h2><p>You can use the predefined CSS variables in your custom styles:</p><table tabindex="0"><thead><tr><th style="text-align:left;">CSS Variable</th><th style="text-align:left;">Font Family</th><th style="text-align:left;">Typical Usage</th></tr></thead><tbody><tr><td style="text-align:left;"><code>var(--font-mc-ten)</code></td><td style="text-align:left;"><code>Minecraft Ten</code></td><td style="text-align:left;">Page H1 headings, Logo branding, Hero main titles</td></tr><tr><td style="text-align:left;"><code>var(--font-mc-seven)</code></td><td style="text-align:left;"><code>Minecraft Seven</code></td><td style="text-align:left;">H2/H3 section titles, Card headers, Sidebar titles</td></tr><tr><td style="text-align:left;"><code>var(--font-mc-five)</code></td><td style="text-align:left;"><code>Minecraft Five</code></td><td style="text-align:left;">Status badges, Version numbers, Small tags</td></tr><tr><td style="text-align:left;"><code>var(--font-noto-bold)</code></td><td style="text-align:left;"><code>Noto Sans Bold</code></td><td style="text-align:left;">Buttons, Input labels, Navigation links</td></tr><tr><td style="text-align:left;"><code>var(--font-noto)</code></td><td style="text-align:left;"><code>Noto Sans</code></td><td style="text-align:left;">Explanatory paragraphs, Body documentation</td></tr><tr><td style="text-align:left;"><code>var(--font-mono)</code></td><td style="text-align:left;"><code>Cascadia Code / Consolas</code></td><td style="text-align:left;">Inline code, Code blocks, Values</td></tr></tbody></table><hr><h2 id="💻-markdown-heading-previews" tabindex="-1">💻 Markdown Heading Previews <a class="header-anchor" href="#💻-markdown-heading-previews" aria-label="Permalink to &quot;💻 Markdown Heading Previews&quot;">​</a></h2><h1 id="heading-level-1-minecraft-ten" tabindex="-1">Heading Level 1 (Minecraft Ten) <a class="header-anchor" href="#heading-level-1-minecraft-ten" aria-label="Permalink to &quot;Heading Level 1 (Minecraft Ten)&quot;">​</a></h1><h2 id="heading-level-2-minecraft-seven" tabindex="-1">Heading Level 2 (Minecraft Seven) <a class="header-anchor" href="#heading-level-2-minecraft-seven" aria-label="Permalink to &quot;Heading Level 2 (Minecraft Seven)&quot;">​</a></h2><h3 id="heading-level-3-minecraft-seven" tabindex="-1">Heading Level 3 (Minecraft Seven) <a class="header-anchor" href="#heading-level-3-minecraft-seven" aria-label="Permalink to &quot;Heading Level 3 (Minecraft Seven)&quot;">​</a></h3><h4 id="heading-level-4-minecraft-five-bold" tabindex="-1">Heading Level 4 (Minecraft Five Bold) <a class="header-anchor" href="#heading-level-4-minecraft-five-bold" aria-label="Permalink to &quot;Heading Level 4 (Minecraft Five Bold)&quot;">​</a></h4><blockquote><p>💡 <strong>Note</strong>: Markdown headings in VitePress documents are automatically styled with the proper font family.</p></blockquote>',16)])])}const v=t(o,[["render",l]]);export{g as __pageData,v as default};
